create database ecom_sales;
use ecom_sales;
create table raw_orders (
order_id varchar(20),
email varchar(100),
customer_name varchar(50),
city varchar(50),
product varchar(50),
category enum('Electronics','Fashion','Food','Drinks'),
price varchar(20),
quantity varchar(20),
order_date varchar(20),
payment_method enum('UPI','COD','Cash','Card','Net Banking')
);


select*from raw_orders;
select*from raw_orders where customer_name is null
or trim(customer_name) = ''
or customer_name regexp '[^A-Za-z ]'
or price not regexp '^[0-9]+$'
or quantity not regexp '^[0-9]+$'
or str_to_date(order_date,'%Y-%m-%d') is null
or payment_method not in ('UPI','COD','Cash','Card','Net banking');



